    VisualSnapshot(id = "zh-hans", mode = ColorMode.Light, locale = "zh-Hans", rightToLeft = false, textSize = SnapshotTextSize.Default),
    // Japanese, in kanji and kana.
    VisualSnapshot(id = "ja", mode = ColorMode.Light, locale = "ja", rightToLeft = false, textSize = SnapshotTextSize.Default),
